BEGIN TRANSACTION;
CREATE TABLE authority (id INTEGER PRIMARY KEY CHECK (id = 1), revision INTEGER NOT NULL CHECK (revision >= 0), state TEXT NOT NULL);
CREATE TABLE events (seq INTEGER PRIMARY KEY AUTOINCREMENT, revision INTEGER NOT NULL, operation_id TEXT NOT NULL REFERENCES operations(operation_id), kind TEXT NOT NULL, provenance TEXT NOT NULL, payload TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE operations (operation_id TEXT PRIMARY KEY, digest TEXT NOT NULL, base_revision INTEGER NOT NULL, revision INTEGER NOT NULL UNIQUE, outcome TEXT NOT NULL);
CREATE TABLE payload_refs (digest TEXT PRIMARY KEY, size INTEGER NOT NULL CHECK (size >= 0), media_type TEXT NOT NULL, first_operation_id TEXT NOT NULL REFERENCES operations(operation_id));
DELETE FROM "sqlite_sequence";
CREATE INDEX events_by_operation ON events(operation_id);
COMMIT;
